import React, { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import categoryProductService from "../services/categoryProductService";
import "./CategoryProductsPage.css"; // Chúng ta sẽ viết CSS ở mục 3

const CategoryProductsPage = () => {
    const { id } = useParams(); // Lấy ID danh mục từ thanh URL trình duyệt
    const [categoryData, setCategoryData] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchProductsByCategory = async () => {
            setLoading(true);
            try {
                // Gọi API tích hợp lọc sản phẩm theo ID danh mục của bạn
                const data = await categoryProductService.getCategoryByIdWithProducts(id);
                setCategoryData(data);
            } catch (error) {
                console.error("Lỗi khi tải sản phẩm theo danh mục:", error);
            } finally {
                setLoading(false);
            }
        };

        if (id) {
            fetchProductsByCategory();
        }
    }, [id]);

    if (loading) {
        return (
            <div className="category-loading-container">
                <div className="spinner-border text-primary" role="status"></div>
                <p>Đang tìm kiếm sản phẩm phù hợp...</p>
            </div>
        );
    }

    if (!categoryData) {
        return (
            <div className="container py-5 text-center">
                <h3>Không tìm thấy danh mục yêu cầu hoặc đã xảy ra lỗi dữ liệu.</h3>
                <Link to="/shop" className="btn btn-primary mt-3">Quay lại cửa hàng</Link>
            </div>
        );
    }

    return (
        <div className="category-products-page">
            <div className="at-container">
                
                {/* Thanh Breadcrumb điều hướng nhỏ */}
                <div className="page-breadcrumb">
                    <Link to="/">Trang chủ</Link>
                    <span>/</span>
                    <Link to="/shop">Sản phẩm</Link>
                    <span>/</span>
                    <strong>{categoryData.name}</strong>
                </div>

                {/* Tiêu đề & Giới thiệu danh mục */}
                <div className="category-intro-header">
                    <h1>Danh mục: {categoryData.name}</h1>
                    {categoryData.description && <p className="cat-desc">{categoryData.description}</p>}
                    <span className="products-count">
                        Tìm thấy <strong>{categoryData.products?.length || 0}</strong> sản phẩm phù hợp
                    </span>
                </div>

                {/* Kiểm tra xem danh mục này có sản phẩm nào không */}
                {categoryData.products && categoryData.products.length > 0 ? (
                    
                    /* BỐ CỤC LƯỚI GRID SẢN PHẨM */
                    <div className="products-grid-layout">
                        {categoryData.products.map((product) => (
                            <div key={product.id} className="product-item-card">
                                
                                {/* Khung chứa ảnh sản phẩm */}
                                <div className="card-image-box">
                                    <img 
                                        src={product.imageUrl || "https://images.unsplash.com/photo-1505693416388-ac5ce068fe85"} 
                                        alt={product.name} 
                                    />
                                    {product.stockQuantity <= 0 && (
                                        <div className="out-of-stock-tag">Hết hàng</div>
                                    )}
                                </div>

                                {/* Nội dung thông tin sản phẩm */}
                                <div className="card-info-box">
                                    <h3 className="item-title" title={product.name}>
                                        {product.name}
                                    </h3>
                                    <p className="item-short-desc">
                                        {product.description || "Sản phẩm nội thất tinh tế cao cấp dành cho không gian sống hiện đại."}
                                    </p>
                                    <div className="item-bottom-row">
                                        <span className="item-price">
                                            {typeof product.price === "number"
                                                ? product.price.toLocaleString("vi-VN", { style: "currency", currency: "VND" })
                                                : product.price}
                                        </span>
                                        <Link to={`/product/${product.id}`} className="view-detail-action-btn">
                                            Xem chi tiết
                                        </Link>
                                    </div>
                                </div>

                            </div>
                        ))}
                    </div>

                ) : (
                    /* Trạng thái trống nếu danh mục chưa có sản phẩm nào */
                    <div className="empty-category-box text-center">
                        <i className="fa-solid fa-face-frown-open empty-icon"></i>
                        <h3>Danh mục này hiện chưa cập nhật sản phẩm</h3>
                        <p>Vui lòng quay lại sau hoặc tham khảo các danh mục sản phẩm khác của AT Design.</p>
                        <Link to="/shop" className="back-shop-btn">Tiếp tục mua sắm</Link>
                    </div>
                )}

            </div>
        </div>
    );
};

export default CategoryProductsPage;
